96	    /**
97	     This safelist allows only text nodes: any HTML Element or any Node other than a TextNode will be removed.
98	     <p>
99	     Note that the output of {@link org.jsoup.Jsoup#clean(String, Safelist)} is still <b>HTML</b> even when using
100	     this Safelist, and so any HTML entities in the output will be appropriately escaped. If you want plain text, not
101	     HTML, you should use a text method such as {@link Element#text()} instead, after cleaning the document.
102	     </p>
103	     <p>Example:</p>
104	     <pre>{@code
105	     String sourceBodyHtml = "<p>5 is &lt; 6.</p>";
106	     String html = Jsoup.clean(sourceBodyHtml, Safelist.none());
107	
108	     Cleaner cleaner = new Cleaner(Safelist.none());
109	     String text = cleaner.clean(Jsoup.parse(sourceBodyHtml)).text();
110	
111	     // html is: 5 is &lt; 6.
112	     // text is: 5 is < 6.
113	     }</pre>
114	
115	     @return safelist
116	     */
117	    public static Safelist none() {
118	        return new Safelist();
119	    }
