223	    /**
224	     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.
225	
226	     @see #basic()
227	     @see #basicWithImages()
228	     @see #simpleText()
229	     @see #relaxed()
230	     */
231	    public Safelist() {
232	        tagNames = new HashSet<>();
233	        attributes = new HashMap<>();
234	        enforcedAttributes = new HashMap<>();
235	        protocols = new HashMap<>();
236	        preserveRelativeLinks = false;
237	    }
