239	    /**
240	     Deep copy an existing Safelist to a new Safelist.
241	     @param copy the Safelist to copy
242	     */
243	    public Safelist(Safelist copy) {
244	        this();
245	        tagNames.addAll(copy.tagNames);
246	        for (Map.Entry<TagName, Set<AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
247	            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
248	        }
249	        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
250	            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
251	        }
252	        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
253	            Map<AttributeKey, Set<Protocol>> attributeProtocolsCopy = new HashMap<>();
254	            for (Map.Entry<AttributeKey, Set<Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
255	                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
256	            }
257	            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
258	        }
259	        preserveRelativeLinks = copy.preserveRelativeLinks;
260	    }
