262	    /**
263	     Add a list of allowed elements to a safelist. (If a tag is not allowed, it will be removed from the HTML.)
264	
265	     @param tags tag names to allow
266	     @return this (for chaining)
267	     */
268	    public Safelist addTags(String... tags) {
269	        Validate.notNull(tags);
270	
271	        for (String tagName : tags) {
272	            Validate.notEmpty(tagName);
273	            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
274	                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
275	            tagNames.add(TagName.valueOf(tagName));
276	        }
277	        return this;
278	    }
279	
280	    /**
281	     Remove a list of allowed elements from a safelist. (If a tag is not allowed, it will be removed from the HTML.)
282	
283	     @param tags tag names to disallow
284	     @return this (for chaining)
285	     */
286	    public Safelist removeTags(String... tags) {
287	        Validate.notNull(tags);
288	
289	        for(String tag: tags) {
290	            Validate.notEmpty(tag);
291	            TagName tagName = TagName.valueOf(tag);
292	
293	            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
294	                attributes.remove(tagName);
295	                enforcedAttributes.remove(tagName);
296	                protocols.remove(tagName);
297	            }
298	        }
299	        return this;
300	    }
