302	    /**
303	     Add a list of allowed attributes to a tag. (If an attribute is not allowed on an element, it will be removed.)
304	     <p>
305	     E.g.: <code>addAttributes("a", "href", "class")</code> allows <code>href</code> and <code>class</code> attributes
306	     on <code>a</code> tags.
307	     </p>
308	     <p>
309	     To make an attribute valid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
310	     <code>addAttributes(":all", "class")</code>.
311	     </p>
312	
313	     @param tag  The tag the attributes are for. The tag will be added to the allowed tag list if necessary.
314	     @param attributes List of valid attributes for the tag
315	     @return this (for chaining)
316	     */
317	    public Safelist addAttributes(String tag, String... attributes) {
318	        Validate.notEmpty(tag);
319	        Validate.notNull(attributes);
320	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
321	
322	        addTags(tag);
323	        TagName tagName = TagName.valueOf(tag);
324	        Set<AttributeKey> attributeSet = new HashSet<>();
325	        for (String key : attributes) {
326	            Validate.notEmpty(key);
327	            attributeSet.add(AttributeKey.valueOf(key));
328	        }
329	        Set<AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
330	        currentSet.addAll(attributeSet);
331	        return this;
332	    }
333	
334	    /**
335	     Remove a list of allowed attributes from a tag. (If an attribute is not allowed on an element, it will be removed.)
336	     <p>
337	     E.g.: <code>removeAttributes("a", "href", "class")</code> disallows <code>href</code> and <code>class</code>
338	     attributes on <code>a</code> tags.
339	     </p>
340	     <p>
341	     To make an attribute invalid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
342	     <code>removeAttributes(":all", "class")</code>.
343	     </p>
344	
345	     @param tag  The tag the attributes are for.
346	     @param attributes List of invalid attributes for the tag
347	     @return this (for chaining)
348	     */
349	    public Safelist removeAttributes(String tag, String... attributes) {
350	        Validate.notEmpty(tag);
351	        Validate.notNull(attributes);
352	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
353	
354	        TagName tagName = TagName.valueOf(tag);
355	        Set<AttributeKey> attributeSet = new HashSet<>();
356	        for (String key : attributes) {
357	            Validate.notEmpty(key);
358	            attributeSet.add(AttributeKey.valueOf(key));
359	        }
360	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
361	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
362	            currentSet.removeAll(attributeSet);
363	
364	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
365	                this.attributes.remove(tagName);
366	        }
367	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
368	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
369	            while (it.hasNext()) {
370	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
371	                Set<AttributeKey> currentSet = entry.getValue();
372	                currentSet.removeAll(attributeSet);
373	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
374	                    it.remove();
375	            }
376	        }
377	        return this;
378	    }
