380	    /**
381	     Add an enforced attribute to a tag. An enforced attribute will always be added to the element. If the element
382	     already has the attribute set, it will be overridden with this value.
383	     <p>
384	     E.g.: <code>addEnforcedAttribute("a", "rel", "nofollow")</code> will make all <code>a</code> tags output as
385	     <code>&lt;a href="..." rel="nofollow"&gt;</code>
386	     </p>
387	
388	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
389	     @param attribute   The attribute name
390	     @param value The enforced attribute value
391	     @return this (for chaining)
392	     */
393	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
394	        Validate.notEmpty(tag);
395	        Validate.notEmpty(attribute);
396	        Validate.notEmpty(value);
397	
398	        TagName tagName = TagName.valueOf(tag);
399	        tagNames.add(tagName);
400	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
401	        AttributeValue attrVal = AttributeValue.valueOf(value);
402	
403	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
404	        attrMap.put(attrKey, attrVal);
405	        return this;
406	    }
