408	    /**
409	     Remove a previously configured enforced attribute from a tag.
410	
411	     @param tag   The tag the enforced attribute is for.
412	     @param attribute   The attribute name
413	     @return this (for chaining)
414	     */
415	    public Safelist removeEnforcedAttribute(String tag, String attribute) {
416	        Validate.notEmpty(tag);
417	        Validate.notEmpty(attribute);
418	
419	        TagName tagName = TagName.valueOf(tag);
420	        if(tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
421	            AttributeKey attrKey = AttributeKey.valueOf(attribute);
422	            Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.get(tagName);
423	            attrMap.remove(attrKey);
424	
425	            if(attrMap.isEmpty()) // Remove tag from enforced attribute map if no enforced attributes are present
426	                enforcedAttributes.remove(tagName);
427	        }
428	        return this;
429	    }
