453	    /**
454	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
455	     URLs with the defined protocol.
456	     <p>
457	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
458	     </p>
459	     <p>
460	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
461	     E.g.: <code>addProtocols("a", "href", "#")</code>
462	     </p>
463	
464	     @param tag       Tag the URL protocol is for
465	     @param attribute       Attribute name
466	     @param protocols List of valid protocols
467	     @return this, for chaining
468	     */
469	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
470	        Validate.notEmpty(tag);
471	        Validate.notEmpty(attribute);
472	        Validate.notNull(protocols);
473	
474	        TagName tagName = TagName.valueOf(tag);
475	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
476	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
477	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
478	
479	        for (String protocol : protocols) {
480	            Validate.notEmpty(protocol);
481	            Protocol prot = Protocol.valueOf(protocol);
482	            protSet.add(prot);
483	        }
484	        return this;
485	    }
486	
487	    /**
488	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
489	     attribute will allow any protocol.
490	     <p>
491	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
492	     </p>
493	
494	     @param tag Tag the URL protocol is for
495	     @param attribute Attribute name
496	     @param removeProtocols List of invalid protocols
497	     @return this, for chaining
498	     */
499	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
500	        Validate.notEmpty(tag);
501	        Validate.notEmpty(attribute);
502	        Validate.notNull(removeProtocols);
503	
504	        TagName tagName = TagName.valueOf(tag);
505	        AttributeKey attr = AttributeKey.valueOf(attribute);
506	
507	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
508	        // be surprising
509	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
510	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
511	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
512	
513	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
514	        for (String protocol : removeProtocols) {
515	            Validate.notEmpty(protocol);
516	            attrProtocols.remove(Protocol.valueOf(protocol));
517	        }
518	
519	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
520	            tagProtocols.remove(attr);
521	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
522	                protocols.remove(tagName);
523	        }
524	        return this;
525	    }
