527	    /**
528	     * Test if the supplied tag is allowed by this safelist.
529	     * @param tag test tag
530	     * @return true if allowed
531	     */
532	    public boolean isSafeTag(String tag) {
533	        return tagNames.contains(TagName.valueOf(tag));
534	    }
