536	    /**
537	     * Test if the supplied attribute is allowed by this safelist for this tag.
538	     * <p>This method does not modify the input element or attribute.</p>
539	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
540	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
541	     * configured protocols when cleaning.</p>
542	     * @param tagName tag to consider allowing the attribute in
543	     * @param el element under test, to confirm protocol
544	     * @param attr attribute under test
545	     * @return true if allowed
546	     */
547	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
548	        TagName tag = TagName.valueOf(tagName);
549	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
550	
551	        Set<AttributeKey> okSet = attributes.get(tag);
552	        if (okSet != null && okSet.contains(key)) {
553	            if (protocols.containsKey(tag)) {
554	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
555	                // ok if not defined protocol; otherwise test. srcset and style URLs are tested per reference in the Cleaner.
556	                return !attrProts.containsKey(key) || isSrcset(attr.getKey()) || isStyle(attr.getKey())
557	                    || (isSoundUrlValue(attr.getValue())
558	                        && isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key)));
559	            } else { // attribute found, no protocols defined, so OK
560	                return true;
561	            }
562	        }
563	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
564	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
565	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
566	            // if the input already has that exact value, treat it as safe
567	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
568	        }
569	        // no attributes defined for tag, try :all tag
570	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
571	    }
