582	    /**
583	     Tests if a single-value URL attribute value is structurally sound for protocol validation. Empty and
584	     whitespace-only values are left to the standard resolution rules. Otherwise, the value must not contain control
585	     characters or whitespace, and must not be a bare scheme (e.g. {@code "mailto:"}) with no content after the
586	     colon.
587	     */
588	    private static boolean isSoundUrlValue(String value) {
589	        if (StringUtil.isBlank(value)) return true; // blank values follow the standard resolution rules
590	        for (int i = 0, length = value.length(); i < length; i++) {
591	            char c = value.charAt(i);
592	            if (c <= 0x20 || c == 0x7f) return false; // control character or whitespace within the URL
593	        }
594	        return !BareScheme.matcher(value).matches();
595	    }
