597	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
598	        for (Protocol protocol : protocols) {
599	            String prot = protocol.toString();
600	
601	            if (prot.equals("#")) { // allows anchor links
602	                if (isValidAnchor(value)) {
603	                    return true;
604	                } else {
605	                    continue;
606	                }
607	            }
608	
609	            String lc = lowerCase(value);
610	            if (lc.startsWith(prot)
611	                && lc.length() > prot.length()
612	                && lc.charAt(prot.length()) == ':') {
613	                return true;
614	            }
615	        }
616	        return false;
617	    }
