650	    /**
651	     Finds the protocol configuration applicable to external references inside an allowed {@code style} attribute on
652	     * the given tag, following the same tag to {@code :all} fallback as the other attribute checks. Unlike a
653	     * {@code href} or {@code srcset}, removing every configured protocol does not open style up to arbitrary
654	     * schemes: when the caller has configured nothing for style (or removed it all), references are restricted to
655	     * the safe default set ({@code http}, {@code https}, and same-document fragments).
656	     */
657	    private Set<Protocol> styleProtocols(TagName tag) {
658	        Set<AttributeKey> okSet = attributes.get(tag);
659	        if (okSet != null && okSet.contains(StyleKey)) {
660	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
661	            if (attrProts != null && attrProts.containsKey(StyleKey)) return attrProts.get(StyleKey);
662	            return DefaultStyleProtocols;
663	        }
664	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
665	        if (enforcedSet != null && enforcedSet.containsKey(StyleKey)) return DefaultStyleProtocols;
666	        return !tag.equals(AllTag) ? styleProtocols(AllTag) : DefaultStyleProtocols;
667	    }
