669	    /**
670	     Validates one external reference found inside a style declaration against the tag's configured style protocols,
671	     * applying the same obfuscation-resistant rules as a {@code srcset} candidate. {@code javascript:} and
672	     * {@code vbscript:} are always rejected (even after control-character stripping and percent-decoding), and so is
673	     * any unknown scheme; a {@code data:} reference passes only when {@code data} is an explicitly allowed protocol
674	     * and its media type is inert. Relative references are resolved against the element's document base URI, and an
675	     * unresolvable reference (such as a relative URL with no base URI) is rejected.
676	     */
677	    boolean isSafeStyleUrl(String tagName, Element el, String url) {
678	        Set<Protocol> protocols = styleProtocols(TagName.valueOf(tagName));
679	        if (!isSoundUrlValue(url)) return false;
680	
681	        // script-bearing schemes are always rejected, after undoing every encoding layer a browser applies
682	        // (HTML entities are already decoded by the parser; CSS escapes by StyleCleaner): strip control bytes and
683	        // leniently percent-decode before testing the prefix
684	        String decoded = lowerCase(stripControlChars(percentDecode(url)));
685	        if (decoded.startsWith("javascript:") || decoded.startsWith("vbscript:")) return false;
686	
687	        if (!isSafeDecodedScheme(url, protocols)) return false;
688	        if (decoded.startsWith("data:") && !isSafeDataUrl(url, protocols)) return false;
689	
690	        // resolve relative references against the document base, applying the same rules as a srcset candidate:
691	        // an unresolvable reference (e.g. no base URI) fails, and the surviving declaration keeps its source spelling
692	        String resolved = StringUtil.resolve(el.baseUri(), url);
693	        if (resolved.isEmpty() && !StringUtil.hasHttpScheme(url)) resolved = url;
694	        return isSafeProtocol(resolved, protocols);
695	    }
