697	    /**
698	     Allows a {@code data:} URL only when {@code data} is an explicitly configured protocol and the embedded media
699	     * type is a known inert type (an image, or plain text); {@code data:text/html}, {@code data:image/svg+xml}, and
700	     * any executable or unknown media type are rejected.
701	     */
702	    private static boolean isSafeDataUrl(String url, Set<Protocol> protocols) {
703	        boolean dataAllowed = false;
704	        for (Protocol protocol : protocols) {
705	            if (protocol.toString().equals("data")) { dataAllowed = true; break; }
706	        }
707	        if (!dataAllowed) return false;
708	        String rest = url.substring("data:".length());
709	        int semi = rest.indexOf(';');
710	        int comma = rest.indexOf(',');
711	        int end = semi >= 0 ? semi : comma;
712	        if (end < 0) end = rest.length();
713	        String mediaType = rest.substring(0, end).trim().toLowerCase(Locale.ROOT);
714	        if (mediaType.isEmpty()) mediaType = "text/plain"; // the default for data: URLs
715	        if (mediaType.startsWith("image/"))
716	            return !mediaType.equals("image/svg+xml"); // SVG can carry script
717	        return mediaType.equals("text/plain");
718	    }
