720	    /**
721	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
722	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
723	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
724	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
725	
726	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
727	     @param el the element the attribute is on, to resolve URLs against its base URI
728	     @param value the source srcset attribute value
729	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
730	     */
731	    String cleanSrcset(String tagName, Element el, String value) {
732	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
733	        StringBuilder sb = StringUtil.borrowBuilder();
734	
735	        int pos = 0, length = value.length();
736	        while (pos <= length) {
737	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
738	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
739	            // separators produce empty candidates, which are invalid.
740	            int start = pos, end = pos;
741	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
742	            boolean started = false; // seen non-whitespace content in this candidate
743	            while (end < length) {
744	                char c = value.charAt(end);
745	                if (c == ',') {
746	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
747	                        end++; // comma is part of the URL
748	                    else
749	                        break; // candidate separator
750	                } else {
751	                    if (isSrcsetSpace(c)) {
752	                        if (started) inUrl = false;
753	                    } else {
754	                        started = true;
755	                    }
756	                    end++;
757	                }
758	            }
759	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
760	            if (end >= length) break;
761	            pos = end + 1; // step past the separator comma
762	        }
763	
764	        if (sb.length() == 0) {
765	            StringUtil.releaseBuilderVoid(sb);
766	            return null;
767	        }
768	        return StringUtil.releaseBuilder(sb);
769	    }
770	
771	    /**
772	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
773	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
774	     */
775	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
776	        // trim ASCII whitespace from the candidate
777	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
778	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
779	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
780	
781	        // the URL is the leading run of non-whitespace
782	        int urlEnd = start;
783	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
784	        String url = value.substring(start, urlEnd);
785	        if (isOrphanDescriptor(url)) return; // a descriptor cannot stand in for the required URL
786	
787	        // an optional descriptor may follow, introduced by at least one ASCII space
788	        String descriptor = null;
789	        if (urlEnd < end) {
790	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
791	            int descStart = urlEnd;
792	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
793	            int descEnd = descStart;
794	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
795	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
796	            descriptor = value.substring(descStart, descEnd);
797	            if (!isValidSrcsetDescriptor(descriptor)) return;
798	        }
799	
800	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
801	
802	        if (sb.length() > 0) sb.append(", ");
803	        sb.append(url);
804	        if (descriptor != null) sb.append(' ').append(descriptor);
805	    }
