807	    /**
808	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
809	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
810	     other. Returns {@code null} when URLs are unrestricted.
811	     */
812	    private Set<Protocol> srcsetProtocols(TagName tag) {
813	        Set<AttributeKey> okSet = attributes.get(tag);
814	        if (okSet != null && okSet.contains(SrcsetKey)) {
815	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
816	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
817	        }
818	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
819	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
820	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
821	    }
