823	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
824	        // apply the same structural rules as for a single-value URL attribute: no control characters or inner
825	        // whitespace, and no bare scheme (e.g. "javascript:") with nothing after the colon
826	        if (!isSoundUrlValue(url)) return false;
827	        // the scheme must still be allowed after percent-decoding and stripping control characters, so that a
828	        // dangerous scheme cannot hide behind e.g. "java%73cript:", "%6Aavascript:", "%00javascript:", or leading
829	        // whitespace and control bytes
830	        if (!isSafeDecodedScheme(url, protocols)) return false;
831	
832	        String value = StringUtil.resolve(el.baseUri(), url);
833	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
834	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
835	        return isSafeProtocol(value, protocols);
836	    }
