838	    /**
839	     Checks the scheme of a candidate URL against the configured protocols, after undoing obfuscations that could hide
840	     a dangerous scheme from a naive prefix check. A real URL scheme is terminated by a <b>literal</b> colon, so the
841	     raw value is scanned for its first colon; percent-encoded bytes and ASCII control characters in the scheme run
842	     before that colon are normalized (e.g. {@code java%73cript:}, {@code %6Aavascript:}, and {@code java%00script:}
843	     all reveal {@code javascript:}). A value with no literal-colon scheme (a relative reference such as
844	     {@code x%3Ay.jpg} or an already-encoded {@code http%3a//host}) is left to the standard base-URI resolution
845	     rules, exactly like a single-value URL attribute. Never throws.
846	     */
847	    private static boolean isSafeDecodedScheme(String url, Set<Protocol> protocols) {
848	        int colon = url.indexOf(':');
849	        if (colon <= 0) return true; // no literal scheme separator: a relative / protocol-relative reference
850	
851	        String head = url.substring(0, colon);
852	        // the scheme run may only contain scheme characters or percent-escapes; anything else (e.g. a leading "//")
853	        // means this colon is not a scheme separator
854	        int length = head.length();
855	        boolean sawEscape = false;
856	        for (int i = 0; i < length; i++) {
857	            char c = head.charAt(i);
858	            if (c == '%') { sawEscape = true; continue; }
859	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
860	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
861	            if (!schemeChar) return true; // not a scheme; defer to base-URI resolution
862	        }
863	        if (!sawEscape) return true; // an unescaped scheme is checked by the normal resolved-URL protocol test
864	
865	        // decode the escaped bytes and drop any revealed control characters, then confirm a well-formed scheme
866	        String decoded = stripControlChars(percentDecode(head));
867	        if (decoded.isEmpty() || !isSchemeAlpha(decoded.charAt(0))) return true;
868	        for (int i = 0; i < decoded.length(); i++) {
869	            char c = decoded.charAt(i);
870	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
871	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
872	            if (!schemeChar) return true; // decoding revealed a non-scheme byte, so it is a relative reference
873	        }
874	
875	        String scheme = lowerCase(decoded);
876	        for (Protocol protocol : protocols) {
877	            String prot = protocol.toString();
878	            if (!prot.equals("#") && scheme.equals(prot)) return true; // the "#" pseudo-protocol never matches a scheme
879	        }
880	        return false;
881	    }
