883	    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL scheme. */
884	    private static String stripControlChars(String value) {
885	        int length = value.length();
886	        StringBuilder stripped = null;
887	        for (int i = 0; i < length; i++) {
888	            char c = value.charAt(i);
889	            if (c <= 0x1f || c == 0x7f) {
890	                if (stripped == null) {
891	                    stripped = new StringBuilder(length);
892	                    stripped.append(value, 0, i);
893	                }
894	            } else if (stripped != null) {
895	                stripped.append(c);
896	            }
897	        }
898	        return stripped != null ? stripped.toString() : value;
899	    }
900	
901	    /**
902	     Leniently decodes {@code %XX} percent-escapes to their (ISO-8859-1 mapped) character. Malformed or incomplete
903	     escapes are left as-is. Used only to reveal an obfuscated URL scheme, so decoding never throws and charset
904	     subtleties outside the ASCII scheme are irrelevant.
905	     */
906	    private static String percentDecode(String url) {
907	        int length = url.length();
908	        if (length < 3 || url.indexOf('%') == -1) return url;
909	        StringBuilder decoded = null;
910	        for (int i = 0; i < length; i++) {
911	            char c = url.charAt(i);
912	            if (c == '%' && i + 2 < length) {
913	                int hi = Character.digit(url.charAt(i + 1), 16);
914	                int lo = Character.digit(url.charAt(i + 2), 16);
915	                if (hi >= 0 && lo >= 0) {
916	                    if (decoded == null) {
917	                        decoded = new StringBuilder(length);
918	                        decoded.append(url, 0, i);
919	                    }
920	                    decoded.append((char) ((hi << 4) | lo));
921	                    i += 2;
922	                    continue;
923	                }
924	            }
925	            if (decoded != null) decoded.append(c);
926	        }
927	        return decoded != null ? decoded.toString() : url;
928	    }
