930	    /**
931	     * Tests if a candidate's first (and only) whitespace-delimited token is a descriptor with no URL in front of it,
932	     * rather than a relative URL. Such an orphan has the <i>shape</i> of a width or density descriptor: a lowercase
933	     * {@code w} or {@code x} suffix, an optional single leading sign, and a non-empty remaining run of only digits and
934	     * dots, e.g. {@code 2x}, {@code 100w}, {@code 1.5x}, {@code 0w}, {@code -1x}, {@code +1x}, {@code 1.x},
935	     * {@code .5x}, or {@code 1.5.2x}. This is a purely syntactic shape test (it does not require the number to be
936	     * valid), because a token that can only be read as a descriptor attempt supplies no decidable URL. A genuine
937	     * relative reference always carries something a descriptor number can never hold — another letter
938	     * ({@code 1e3x}, {@code 1X}, {@code 2x.jpg}), a path separator ({@code ../2x}), or an internal or second sign
939	     * ({@code 1-2x}, {@code ++2x}) — and so is never mistaken for an orphan.
940	     */
941	    private static boolean isOrphanDescriptor(String token) {
942	        int length = token.length();
943	        if (length < 2) return false; // a bare "w"/"x" is a possible relative reference, not a descriptor attempt
944	        char suffix = token.charAt(length - 1);
945	        if (suffix != 'w' && suffix != 'x') return false;
946	        int i = 0;
947	        if (token.charAt(0) == '+' || token.charAt(0) == '-') i++; // at most one, leading sign
948	        if (i == length - 1) return false; // just a sign and suffix (e.g. "+w"): a relative reference, not a number
949	        for (; i < length - 1; i++) {
950	            char c = token.charAt(i);
951	            boolean numberChar = (c >= '0' && c <= '9') || c == '.';
952	            if (!numberChar) return false; // a letter, separator, or internal sign marks a real URL
953	        }
954	        return true;
955	    }
