957	    /**
958	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
959	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
960	     Signs, exponents, a dot missing a side, and zero values are all invalid.
961	     */
962	    private static boolean isValidSrcsetDescriptor(String descriptor) {
963	        int length = descriptor.length();
964	        if (length < 2) return false;
965	        String number = descriptor.substring(0, length - 1);
966	        switch (descriptor.charAt(length - 1)) {
967	            case 'w': return isPositiveInteger(number);
968	            case 'x': return isPositiveNumber(number);
969	            default:  return false;
970	        }
971	    }
