973	    /** Tests if the value is all digits and greater than zero. */
974	    private static boolean isPositiveInteger(String number) {
975	        boolean nonZero = false;
976	        for (int i = 0, length = number.length(); i < length; i++) {
977	            char c = number.charAt(i);
978	            if (c < '0' || c > '9') return false;
979	            if (c != '0') nonZero = true;
980	        }
981	        return nonZero;
982	    }
983	
984	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
985	    private static boolean isPositiveNumber(String number) {
986	        int dot = number.indexOf('.');
987	        if (dot == -1) return isPositiveInteger(number);
988	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
989	        String integer = number.substring(0, dot);
990	        String fraction = number.substring(dot + 1);
991	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
992	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
993	    }
994	
995	    private static boolean isDigits(String value) {
996	        for (int i = 0, length = value.length(); i < length; i++) {
997	            char c = value.charAt(i);
998	            if (c < '0' || c > '9') return false;
999	        }
1000	        return value.length() > 0;
1001	    }
