1003	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
1004	    private static boolean isSrcsetSpace(char c) {
1005	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
1006	    }
