1008	    /** Tests if the character is an ASCII letter, the required first character of a URL scheme. */
1009	    private static boolean isSchemeAlpha(char c) {
1010	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
1011	    }
