1023	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
1024	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
1025	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
1026	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
1027	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
1028	        }
1029	
1030	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
1031	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
1032	
1033	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
1034	    }
