194	    /**
195	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
196	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
197	     */
198	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
199	        if (structurallyBad) return;
200	        int p = skipSpaceAndComments(value, start, end);
201	        if (p < 0) return; // an unterminated leading comment rejects only this declaration
202	        int q = end;
203	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
204	        if (p == q) return; // whitespace-only fragment, e.g. from a duplicated ';'
205	        int nameStart = p;
206	
207	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
208	        if (value.charAt(p) == '@') {
209	            if (isSafeImportDeclaration(value, p, q)) append(out, value, start, q);
210	            return;
211	        }
212	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
213	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
214	        boolean custom = false;
215	        if (value.charAt(p) == '-') {
216	            if (p + 1 < end && value.charAt(p + 1) == '-') {
217	                p += 2;
218	                custom = true;
219	                if (p >= q || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
220	                while (p < q && isIdentChar(value.charAt(p))) p++;
221	            } else {
222	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
223	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
224	            }
225	        }
226	        if (!custom) {
227	            if (p >= q || !isIdentStart(value.charAt(p))) return; // no property name
228	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
229	        }
230	        int afterName = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
231	        if (afterName < 0) return; // an unterminated or unsafe comment in the gap rejects only this declaration
232	        if (afterName >= q || value.charAt(afterName) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
233	        p = afterName + 1; // step past ':'
234	
235	        if (isDangerousProperty(value, nameStart)) return; // known script-entry properties, regardless of value
236	        // a custom property (--name) holds arbitrary free text: its value is scanned as one string, so a colon that is
237	        // not part of a reference (e.g. "--x: https://example.com" or a time such as "12:00"), a stray quote, or an
238	        // at-keyword other than @import is preserved verbatim; only its references decide its fate
239	        boolean safe = custom
240	            ? freeTextIsSafe(value.substring(p, q))
241	            : referencesAreSafe(value, p, q);
242	        if (safe) append(out, value, start, q);
243	    }
