285	    /**
286	     Advances past CSS whitespace and complete block comments. A comment is inert token separators (a browser removes
287	     it before tokenization), so its text is never inspected for a concealed reference; an unterminated comment is
288	     still an unbounded fragment and yields {@code -1}, rejecting only the declaration that contains it.
289	     */
290	    private int skipSpaceAndComments(String value, int i, int end) {
291	        while (i < end) {
292	            char c = value.charAt(i);
293	            if (isCssSpace(c)) { i++; continue; }
294	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
295	                int close = value.indexOf("*/", i + 2);
296	                if (close < 0 || close >= end) return -1;
297	                i = close + 2;
298	                continue;
299	            }
300	            break;
301	        }
302	        return i;
303	    }
304	
305	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url /**\/ ( ... )}). */
306	    private int skipSeparators(String value, int i, int end) {
307	        return skipSpaceAndComments(value, i, end);
308	    }
309	
310	    /**
311	     Tests whether a comment-only separator (no whitespace) from {@code nameEnd} glues the preceding identifier run
312	     to another identifier run that is itself followed (optionally via separators) by {@code (}. A comment wedged
313	     between two identifier runs ({@code ur/**\/l( ... )} or {@code expr/**\/ession( ... )}) does not join them under
314	     a strict CSS tokenizer, but a lenient engine could read the glued run as a single function token; such a
315	     declaration is rejected rather than risk a split {@code url} or {@code expression} escaping recognition. Real
316	     whitespace keeps the runs distinct tokens, and two bare runs without a following call ({@code a/**\/b}) stay
317	     untouched. The second run is read with full escape semantics so that an escaped continuation such as
318	     {@code ur/**\/\6c( ... )} is just as ambiguous.
319	     */
320	    private boolean commentGluesIdentToCall(String value, int nameEnd, int end) {
321	        int i = nameEnd;
322	        boolean sawComment = false;
323	        while (i < end) {
324	            char c = value.charAt(i);
325	            if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
326	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
327	                int close = value.indexOf("*/", i + 2);
328	                if (close < 0 || close > end) return false;
329	                sawComment = true;
330	                i = close + 2;
331	                continue;
332	            }
333	            break; // reached the start of whatever the separator abuts
334	        }
335	        if (!sawComment) return false;
336	        if (i >= end || !(isIdentStart(value.charAt(i)) || value.charAt(i) == '\\'))
337	            return false; // the separator must glue onto another identifier run
338	        StringBuilder glued = new StringBuilder();
339	        int k = scanIdent(value, i, end, glued);
340	        k = skipSeparators(value, k, end);
341	        return k >= 0 && k < end && value.charAt(k) == '(';
342	    }
343	
344	    /**
345	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
346	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}. The name is
347	     * the plain identifier run starting at {@code nameStart}; a comment appended to the name cannot change the
348	     * comparison.
349	     */
350	    private boolean isDangerousProperty(String value, int nameStart) {
351	        int p = nameStart;
352	        while (p < value.length() && isIdentChar(value.charAt(p))) p++;
353	        String name = value.substring(nameStart, p);
354	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
355	    }
356	
357	    /**
358	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
359	     recognized exactly as in declaration splitting. Block comments and the contents of ordinary quoted strings are
360	     inert token separators (their text is emitted verbatim but never fetched or tokenized as a call); a quoted
361	     string is still checked when it is the actual argument of a {@code url()} call. Every {@code url(...)}
362	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is read with full CSS
363	     escape semantics, so a hex or character escape, consecutive backslashes, or a case change in the function name
364	     ({@code \75 rl(...)}, a backslash-escaped {@code URL}, {@code \65 xpression(...)}) reaches the same decision as the plain
365	     spelling. Unbalanced parentheses, an unterminated string or comment, or any failed reference check rejects the
366	     declaration.
367	     */
368	    private boolean referencesAreSafe(String value, int start, int end) {
369	        int parenDepth = 0;
370	        int i = start;
371	        while (i < end) {
372	            char c = value.charAt(i);
373	            if (c == '"' || c == '\'') {
374	                int[] quote = scanQuoted(value, i + 1, c);
375	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
376	                // an identifier run glued directly to the string and followed by a call (e.g. u"rl"(...)) is a
377	                // syntax error a strict browser discards but a lenient one could read as one escaped function name
378	                if (stringGluesIdentToCall(value, i, quote[0], end)) return false;
379	                // ordinary string content is inert: it is never fetched as a reference (a quoted url() argument is
380	                // checked separately by isSafeUrlArgument)
381	                i = quote[0] + 1;
382	                continue;
383	            }
384	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
385	                int close = value.indexOf("*/", i + 2);
386	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
387	                i = close + 2; // comment text is inert token separators, never a concealed declaration or call
388	                continue;
389	            }
390	            if (c == '(') { parenDepth++; i++; continue; }
391	            if (c == ')') {
392	                if (parenDepth == 0) return false; // unmatched ')'
393	                parenDepth--;
394	                i++;
395	                continue;
396	            }
397	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
398	            if (isIdentStart(c) || c == '-' || c == '\\') {
399	                StringBuilder decoded = new StringBuilder();
400	                int nameEnd = scanIdent(value, i, end, decoded);
401	                String fnName = decoded.toString();
402	                int j = skipSeparators(value, nameEnd, end);
403	                if (j < 0) return false; // an unterminated comment after the name rejects the declaration
404	                if (commentGluesIdentToCall(value, nameEnd, end)) return false; // e.g. ur/**/l(...)
405	                if (j < end && value.charAt(j) == '(') {
406	                    int argEnd = matchingParen(value, j + 1, end);
407	                    if (argEnd < 0) return false;
408	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
409	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
410	                    if (!isPlainName(fnName)) return false;
411	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
412	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
413	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
414	                    continue;
415	                }
416	                i = nameEnd;
417	                continue;
418	            }
419	            i++;
420	        }
421	        return parenDepth == 0;
422	    }
