490	    /**
491	     Applies the same reference rules to text that is not itself parsed as declarations — the free-form value of a
492	     custom property. As in an ordinary value, quoted strings and comments are inert token separators (a fake call
493	     written inside either never fetches), while every real {@code url(...)} (its name possibly hex- or
494	     character-escaped), {@code @import}, and the legacy {@code expression(...)} function is normalized and checked.
495	     */
496	    private boolean freeTextIsSafe(String text) {
497	        int end = text.length();
498	        int i = 0;
499	        while (i < end) {
500	            char c = text.charAt(i);
501	            if (c == '"' || c == '\'') {
502	                int[] quote = scanQuoted(text, i + 1, c);
503	                if (quote[1] != 1) return false;
504	                if (stringGluesIdentToCall(text, i, quote[0], end)) return false; // e.g. "u"rl(...) or ur"l"(...)
505	                i = quote[0] + 1;
506	                continue;
507	            }
508	            if (c == '/' && i + 1 < end && text.charAt(i + 1) == '*') {
509	                int close = text.indexOf("*/", i + 2);
510	                if (close < 0) return false;
511	                i = close + 2;
512	                continue;
513	            }
514	            if (c == '@') {
515	                StringBuilder atName = new StringBuilder();
516	                int nameEnd = scanIdent(text, i + 1, end, atName);
517	                if (atName.toString().equalsIgnoreCase("import") && !freeTextImportIsSafe(text, nameEnd, end))
518	                    return false;
519	                i = nameEnd > i + 1 ? nameEnd : i + 1;
520	                continue;
521	            }
522	            if (isIdentStart(c) || c == '-' || c == '\\') {
523	                StringBuilder decoded = new StringBuilder();
524	                int nameEnd = scanIdent(text, i, end, decoded);
525	                int j = skipSeparators(text, nameEnd, end);
526	                if (j < 0) return false;
527	                if (commentGluesIdentToCall(text, nameEnd, end)) return false; // e.g. ur/**/l(...)
528	                if (j < end && text.charAt(j) == '(') {
529	                    String fnName = decoded.toString();
530	                    int argEnd = matchingParen(text, j + 1, end);
531	                    if (argEnd < 0) return false;
532	                    if (!isPlainName(fnName)) return false;
533	                    if (fnName.equalsIgnoreCase("expression")) return false;
534	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
535	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
536	                    continue;
537	                }
538	                i = nameEnd;
539	                continue;
540	            }
541	            i++;
542	        }
543	        return true;
544	    }
545	
546	    /**
547	     Tests whether a quoted string at {@code [open, close]} is glued without whitespace to identifier runs on
548	     either side and followed by a call: {@code "u"rl(...)}, {@code ur"l"(...)}, or {@code u"rl"(...)}. Such
549	     token sequences are value syntax errors a strict browser discards, but a lenient engine could read the glued
550	     runs as one escaped {@code url} or {@code expression} call, so the declaration is rejected rather than risk a
551	     split name escaping recognition. The adjacent runs are read with full escape semantics. Ordinary tokens
552	     separated from the string by whitespace (such as a real {@code url(...)} later in the value) are unaffected.
553	     */
554	    private boolean stringGluesIdentToCall(String value, int open, int close, int end) {
555	        boolean gluedBefore = open > 0 && isIdentChar(value.charAt(open - 1));
556	        int after = close + 1;
557	        boolean gluedAfter = after < end && (isIdentStart(value.charAt(after)) || value.charAt(after) == '\\');
558	        if (!gluedBefore && !gluedAfter) return false;
559	        int k = after;
560	        if (gluedAfter) {
561	            StringBuilder ignored = new StringBuilder();
562	            k = scanIdent(value, k, end, ignored);
563	        }
564	        k = skipSeparators(value, k, end);
565	        return k >= 0 && k < end && value.charAt(k) == '(';
566	    }
567	
568	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
569	    private boolean freeTextImportIsSafe(String text, int from, int end) {
570	        int i = skipSeparators(text, from, end);
571	        if (i < 0) return false;
572	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
573	        char c = text.charAt(i);
574	        if (c == '"' || c == '\'') {
575	            int[] quote = scanQuoted(text, i + 1, c);
576	            if (quote[1] != 1) return false;
577	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
578	        }
579	        if (isIdentStart(c) || c == '-' || c == '\\') {
580	            StringBuilder fnName = new StringBuilder();
581	            int nameEnd = scanIdent(text, i, end, fnName);
582	            int k = skipSeparators(text, nameEnd, end);
583	            if (k < 0 || k >= end || text.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
584	            int argEnd = matchingParen(text, k + 1, end);
585	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
586	        }
587	        return false;
588	    }
589	
590	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
591	    private boolean isSafeUrlArgument(String value, int from, int end) {
592	        int i = from;
593	        while (i < end && isCssSpace(value.charAt(i))) i++;
594	        int j = end;
595	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
596	        if (i == j) return false; // url() with no reference
597	
598	        char first = value.charAt(i);
599	        String raw;
600	        if (first == '"' || first == '\'') {
601	            int[] quote = scanQuoted(value, i + 1, first);
602	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
603	            raw = value.substring(i + 1, quote[0]);
604	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
605	                char c = raw.charAt(k);
606	                if (c == '\\') { k++; continue; }
607	                if (c == first) return false;
608	            }
609	        } else {
610	            // an unquoted URL token is a single run: a bare quote or whitespace is a syntax error, not part of the
611	            // URL. Whitespace that is the delimiter of a hex escape (or a whitespace character itself escaped) is
612	            // part of the escape and so stays in the run, exactly as a browser reads it.
613	            int k = i;
614	            while (k < j) {
615	                char c = value.charAt(k);
616	                if (c == '\\') {
617	                    int[] escape = consumeEscape(value, k, j);
618	                    if (escape[1] < 0) return false; // a lone trailing backslash is no URL token
619	                    k = escape[0];
620	                    continue;
621	                }
622	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
623	                k++;
624	            }
625	            raw = value.substring(i, j);
626	        }
627	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
628	    }
629	
630	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
631	    private int matchingParen(String value, int from, int end) {
632	        int depth = 1;
633	        int i = from;
634	        while (i < end) {
635	            char c = value.charAt(i);
636	            if (c == '\\') { i += 2; continue; }
637	            if (c == '"' || c == '\'') {
638	                int[] quote = scanQuoted(value, i + 1, c);
639	                if (quote[1] != 1) return -1;
640	                i = quote[0] + 1;
641	                continue;
642	            }
643	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
644	                int close = value.indexOf("*/", i + 2);
645	                if (close < 0 || close >= end) return -1; // an unterminated comment leaves the function unclosed
646	                i = close + 2;
647	                continue;
648	            }
649	            if (c == '(') depth++;
650	            else if (c == ')') { depth--; if (depth == 0) return i; }
651	            i++;
652	        }
653	        return -1;
654	    }
655	
656	    /**
657	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
658	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
659	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
660	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
661	     CSS requirement to replace it.
662	     */
663	    static String unescape(String value) {
664	        if (value.indexOf('\\') == -1) return value;
665	        int length = value.length();
666	        StringBuilder sb = null;
667	        int i = 0;
668	        while (i < length) {
669	            char c = value.charAt(i);
670	            if (c == '\\' && i + 1 < length) {
671	                if (sb == null) {
672	                    sb = new StringBuilder(length);
673	                    sb.append(value, 0, i);
674	                }
675	                int h = i + 1;
676	                int hexEnd = h;
677	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
678	                if (hexEnd > h) {
679	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
680	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
681	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
682	                    if (code == 0 || code > Character.MAX_CODE_POINT
683	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
684	                        code = 0xFFFD;
685	                    sb.appendCodePoint(code);
686	                    i = hexEnd;
687	                } else {
688	                    sb.append(value.charAt(i + 1));
689	                    i += 2;
690	                }
691	                continue;
692	            }
693	            if (sb != null) sb.append(c);
694	            i++;
695	        }
696	        return sb != null ? sb.toString() : value;
697	    }
698	
699	    private static boolean isCssSpace(char c) {
700	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
701	    }
702	
703	    private static boolean isHex(char c) {
704	        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
705	    }
706	
707	    private static boolean isIdentStart(char c) {
708	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
709	    }
710	
711	    private static boolean isIdentChar(char c) {
712	        return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-';
713	    }
714	}
