import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class StyleProbe {
    static String clean(String html, String base, Safelist sl) {
        Document d = Jsoup.parse(html, base);
        Document c = new Cleaner(sl).clean(d);
        return c.body().html().replace("\n", "");
    }
    public static void main(String[] a) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        Safelist data = Safelist.relaxed().addAttributes(":all", "style")
            .addProtocols(":all", "style", "http", "https", "data");
        String base = "https://example.com/a/b.html";
        String[] cases = {
            "<div style=\"background:url(//evil.com/x.png)\">",          // protocol-relative
            "<div style=\"background:url(//evil.com)\">",                // protocol-relative no path
            "<div style=\"background:url(x.png)\">",                     // relative w/ base
            "<div style=\"background:url(/abs.png)\">",                  // root-relative w/ base
            "<div style=\"color:red;background:url(javascript:alert(1))\">", // js + safe
            "<div style=\"background:url(jAvAsCrIpT:alert(1))\">",       // case
            "<div style=\"background:url(&#106;avascript:alert(1))\">",   // entity (parser decodes?)
            "<div style=\"background:url(java%73cript:1)\">",            // percent
            "<div style=\"background:url(java\\73 cript:1)\">",          // css escape
            "<div style=\"background:url(\u0000javascript:1)\">",        // control
            "<div style=\"background:url(data:image/png;base64,AAAA)\">",// data not allowed
            "<div style=\"color:red;;font-weight:bold;;\">",             // dup semis
            "<div style='font-family:\"Calibri;\";color:red'>",          // semi in string
            "<div style=\"background:url(/img;a.png)\">",                // semi in paren
            "<div style=\"color:red;/* unterminated\">",                 // unclosed comment
            "<div style=\"x:1;background:url(//evil.com);y:2\">",        // pr between safe
            "<div style=\"background:url(  https://safe.com/a.png  )\">",// ws around
        };
        for (String s : cases) System.out.println(s.replace("\u0000","<NUL>") + "  =>  " + clean(s, base, sl));
        // no base
        System.out.println("NO-BASE: " + clean("<div style=\"background:url(x.png)\">", "", sl));
        System.out.println("DATA:    " + clean("<div style=\"background:url(data:image/png;base64,AAAA);color:red\">", base, data));
        System.out.println("DATA-SVG:" + clean("<div style=\"background:url(data:image/svg+xml;base64,AAAA)\">", base, data));
    }
}
EOF
