import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class StyleProbe2 {
    static String clean(String html, String base, Safelist sl) {
        Document d = Jsoup.parseBodyFragment(html, base);
        return new Cleaner(sl).clean(d).body().html().replace("\n", "");
    }
    public static void main(String[] a) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        String base = "https://example.com/a/b";
        String[] cases = {
            "<div style=\"background:url(//evil.com/x)\">",
            "<div style=\"background:url(/\\evil.com/x)\">",
            "<div style=\"background:url(\\/\\/evil.com/x)\">",
            "<div style=\"background:url(\\\\\\\\evil.com)\">",
            "<div style=\"background:url(\\2f\\2fevil.com)\">",
            "<div style=\"background:url(\\2f /\\2f evil.com)\">",
            "<div style=\"background:url('#//evil.com')\">",
            "<div style=\"background:url('/x.png')\">",
            "<div style=\"@import '//evil.com/x.css';color:red\">",
            "<div style=\"background:url(//evil.com/x);color:red\">",
            "<div style=\"background:url(http\\\\af0aab x);color:red\">",
            "<div style=\"background:url(//evil.com/x)\">",
        };
        for (String s : cases) System.out.println(s + "  =>  " + clean(s, base, sl));
        // no base uri via Jsoup.clean(html, safelist)
        System.out.println("Jsoup.clean no-base: " + Jsoup.clean("<div style=\"background:url(x.png);color:red\">x</div>", sl));
    }
}
EOF
