/**
 Tests whether an (already CSS-unescaped, percent-decoded, control-stripped, lower-cased) reference begins with an
 authority component with no scheme of its own — {@code //host}, or the backslash spellings ({@code \\host},
 {@code /\host}) a browser's special-scheme URL parser normalizes to the same form. Such a protocol-relative
 reference inherits the base document's scheme and is never an allowed, independently-schemed absolute URL. A
 single leading slash (a root-relative reference such as {@code /img.png}) does not match and stays resolvable.
 */
private static boolean startsWithAuthority(String decoded) {
    return decoded.length() >= 2
        && isAuthoritySlash(decoded.charAt(0))
        && isAuthoritySlash(decoded.charAt(1));
}

private static boolean isAuthoritySlash(char c) {
    return c == '/' || c == '\\';
}

