import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class StyleProbe3 {
    static String clean(String html, String base, Safelist sl) {
        Document d = Jsoup.parseBodyFragment(html, base);
        return new Cleaner(sl).clean(d).body().html().replace("\n", "");
    }
    public static void main(String[] a) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        String base = "https://example.com/a/b";
        // NUL via HTML entity, leading/trailing control chars
        System.out.println(clean("<div style=\"background:url(&#0;javascript:1)\">x</div>", base, sl));
        System.out.println(clean("<div style=\"background:url(java&#x00;script:1)\">x</div>", base, sl));
        System.out.println(clean("<div style=\"background:url(javascript:1&#1;)\">x</div>", base, sl));
        // multiple elements stay independent; one malformed doesn't change another
        String multi = "<p style=\"color:red;x:1\">a</p>"
            + "<div style=\"background:url(//evil);font:1\">b</div>"
            + "<span style=\"background:url(img/x.png)\">c</span>";
        System.out.println(clean(multi, base, sl));
        // isolation: mutate returned copy, input unaffected
        Document in = Jsoup.parseBodyFragment("<div style=\"color:red;background:url(javascript:1)\">x</div>", base);
        String inBefore = in.body().html();
        Document out = new Cleaner(sl).clean(in);
        out.body().child(0).attr("style", "background:url(javascript:999)");
        System.out.println("input-unchanged=" + in.body().html().replace("\n","").equals(inBefore.replace("\n","")));
        System.out.println("repeat-stable=" + clean(clean(multi, base, sl), base, sl).equals(clean(multi, base, sl)));
    }
}
