    }
    static String c(String html){ return c(html, "https://example.com/a/b"); }
    public static void main(String[] x){
        String[] t = {
            "<div style=\"background:url(/**///evil.com/x)\">",          // comment leading inside url()
            "<div style=\"background:url(/* */ //evil.com/x)\">",       // comment+space then //
            "<div style=\"background:url(//evil.com/* */x.png)\">",     // PR then comment
            "<div style=\"background:url(/%2fevil)\">",                 // percent slash at pos1
            "<div style=\"background:url(&#47;&#47;evil.com/x)\">",     // numeric entities -> //
            "<div style=\"background:url(&sol;&sol;evil.com/x)\">",     // named &sol;
            "<div style=\"color:red;background:url(x.png\">",           // truncated, unclosed fn
            "<div style=\"background:url('//evil.com/x')\">",           // quoted PR
            "<div style=\"background:url(&quot;//evil.com/x&quot;)\">", // entity quotes around PR
            "<div style=\"background:url(//evil.com/x)\">",             // plain PR
            "<div style='background:url(\"/a b.png\")'>",               // quoted relative with space
            "<div style=\"background:url('/a b.png')\">",               // quoted rel with space
            "<div style=\"background:url(  )\">",                       // empty url
        };
        for(String s:t) System.out.println(s+"\n   => "+c(s));
        // preserveRelativeLinks with dummy base
        Safelist prs = new Safelist().addTags("div").addAttributes("div","style").preserveRelativeLinks(true);
        System.out.println("PRL rel:  "+Jsoup.clean("<div style=\"background:url(x.png)\">x</div>", prs));
        System.out.println("PRL //:   "+Jsoup.clean("<div style=\"background:url(//evil/x)\">x</div>", prs));
        // show parsed attribute value for literal NUL vs entity
        Document d1 = Jsoup.parseBodyFragment("<div style=\"background:url(\u0000javascript:1)\">", "https://e.com/a");
        Document d2 = Jsoup.parseBodyFragment("<div style=\"background:url(&#0;javascript:1)\">", "https://e.com/a");
        String v1 = d1.body().child(0).attr("style");
        String v2 = d2.body().child(0).attr("style");
        System.out.printf("literal-NUL char after 'url(' = U+%04X%n", (int)v1.charAt(v1.indexOf("url(")+4));
        System.out.printf("entity-NUL  char after 'url(' = U+%04X%n", (int)v2.charAt(v2.indexOf("url(")+4));
    }
}
